#!/usr/bin/env bash
# rv32 function-model vs Spike (rv32imafdb): the cpu-tests of trace-model (integer), the directed F/D tests (generated by
# tests/rv64/gen_fp.py and gen_fp_trap.py with xlen 32) and compiler-generated FP code, and the official riscv-tests rv32uf / rv32ud.
#   usage: tests/rv32/run.sh <work-dir>     env: SPIKE_SRC / SPIKE_BUILD (see scripts/build_spike.sh), TRACE (trace-model checkout, default ../trace-model),
#                                                RISCV_TESTS (see tests/rv64/riscv-tests-fp.sh)
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/../.." && pwd); W=${1:?work dir}; TRACE=${TRACE:-$ROOT/../trace-model}
mkdir -p "$W"
XLEN=32 OUT="$W/sp32" bash "$ROOT/scripts/build_spike.sh" >/dev/null
python3 "$ROOT/tests/rv64/gen_fp.py" "$W/gen" 32 >/dev/null
python3 "$ROOT/tests/rv64/gen_fp_trap.py" "$W/gen" 32 >/dev/null
cp "$ROOT/tests/rv64/fp-kernels.c" "$W/gen/"
export CMODEL=medlow TARGET=riscv32 ABI=ilp32d EXTRA_DIR="$W/gen"
ARCH=rv32imafd_zicsr_zifencei bash "$TRACE/scripts/build_tests.sh" "$TRACE" "$W/t32" rv32-fp rv32-fp-trap fp-kernels $(cd "$TRACE/baremetal/test/cpu-tests" && ls *.c | sed 's/\.c$//' | grep -v -E '^(zfinx|matmul_)') | grep -v ' OK$' || true
pass=0; fail=0
for d in "$W"/t32/*/; do
  t=$(basename "$d"); [ -f "$d/$t.bin" ] || continue
  if REF_UNBUF=1 perl -e 'alarm 900; exec @ARGV' "$W/sp32/a.out" --image "$d/$t.bin" --diff 2>&1 | grep -q 'Success'; then pass=$((pass+1)); else fail=$((fail+1)); echo "FAIL $t"; fi
done
echo "rv32 vs Spike: pass=$pass fail=$fail (load-store, software-interrupt-vectored and timer-interrupt-mask are the known differences)"
XLEN=32 SPIKE_OUT="$W/sp32/a.out" bash "$ROOT/tests/rv64/riscv-tests-fp.sh" "$W/rt"
